using System.Text.Json;
using System.Globalization;
using System.Windows.Data;
namespace SmartLedger.App.Converters;
public sealed class AuditDisplayConverter : IValueConverter {
 static readonly Dictionary<string,string> A=new(StringComparer.OrdinalIgnoreCase) { ["LOGIN_SUCCESS"]="تسجيل دخول ناجح",["LOGIN_FAILED"]="فشل تسجيل الدخول",["LOGOUT"]="تسجيل الخروج",["CREATE"]="إنشاء سجل",["UPDATE"]="تعديل سجل",["DELETE"]="حذف سجل",["USER_CREATED"]="إنشاء مستخدم",["USER_UPDATED"]="تعديل مستخدم",["USER_DELETED"]="حذف مستخدم",["USER_ACTIVATED"]="تفعيل مستخدم",["USER_DEACTIVATED"]="تعطيل مستخدم" };
 static readonly Dictionary<string,string> E=new(StringComparer.OrdinalIgnoreCase) { ["User"]="مستخدم",["Users"]="المستخدمون",["Person"]="شخص",["Book"]="دفتر",["Operation"]="عملية",["Product"]="منتج",["StockMovement"]="حركة مخزون",["Invoice"]="فاتورة",["Expense"]="مصروف",["Settings"]="الإعدادات" };
 public object Convert(object value,Type targetType,object parameter,CultureInfo culture) { var s=value?.ToString()??""; var k=parameter?.ToString()??""; if(string.IsNullOrWhiteSpace(s))return "—"; if(k=="Action")return A.TryGetValue(s,out var a)?a:s; if(k=="Entity")return E.TryGetValue(s,out var e)?e:s; if(k=="Date"){DateTimeOffset d; if(value is DateTimeOffset dto)d=dto.ToLocalTime();else if(value is DateTime dt)d=new DateTimeOffset(dt);else if(!DateTimeOffset.TryParse(s,CultureInfo.InvariantCulture,DateTimeStyles.RoundtripKind,out d))return s;return d.ToString("dd/MM/yyyy — hh:mm tt",CultureInfo.InvariantCulture).Replace("AM","ص").Replace("PM","م");} if(k=="Details"){try{using var doc=JsonDocument.Parse(s);if(doc.RootElement.ValueKind==JsonValueKind.Object){var p=new List<string>();foreach(var x in doc.RootElement.EnumerateObject()){var label=x.Name switch {"UserName"=>"اسم المستخدم","DisplayName"=>"الاسم","Name"=>"الاسم","Id"=>"المعرّف","Reason"=>"السبب","Count"=>"العدد","Status"=>"الحالة","OldValue"=>"القيمة السابقة","NewValue"=>"القيمة الجديدة",_=>x.Name};p.Add(label+": "+(x.Value.ValueKind==JsonValueKind.String?x.Value.GetString():x.Value.GetRawText()));}return p.Count==0?"لا توجد تفاصيل إضافية":string.Join(" ؛ ",p);}return doc.RootElement.ValueKind==JsonValueKind.String?doc.RootElement.GetString()??"—":doc.RootElement.ToString();}catch{return s;}} return s; }
 public object ConvertBack(object value,Type targetType,object parameter,CultureInfo culture)=>Binding.DoNothing;
}
